// HasLabel applies the HasEdge predicate on the "label" edge.
func HasLabel() predicate.DictLabelI18n {
	return predicate.DictLabelI18n(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, LabelTable, LabelColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasLabelWith applies the HasEdge predicate on the "label" edge with a given conditions (other predicates).
func HasLabelWith(preds ...predicate.DictLabel) predicate.DictLabelI18n {
	return predicate.DictLabelI18n(func(s *sql.Selector) {
		step := newLabelStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DictLabelI18n) predicate.DictLabelI18n {
	return predicate.DictLabelI18n(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DictLabelI18n) predicate.DictLabelI18n {
	return predicate.DictLabelI18n(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DictLabelI18n) predicate.DictLabelI18n {
	return predicate.DictLabelI18n(sql.NotPredicates(p))
}
